import React from "react";

// Import portfolio images
import stock from "../img/image1.jpg";
import stock1 from "../img/image2.jpg";
import stock2 from "../img/image3.jpg";
import stock3 from "../img/image4.jpg";
import stock4 from "../img/image5.jpg";
import stock5 from "../img/image6.jpg";

class Portfolio extends React.Component {
  render() {
    // Portfolio items data
    const projects = [
      {
        id: 1,
        title: "Emotion Recognition System",
        category: "ReactJS • Node.js • Python • ML",
        mainImage: stock,
        gallery: [stock1, stock2, stock3],
      },
      {
        id: 2,
        title: "Flip Emoji Match Game",
        category: "JavaScript • CSS3 • React",
        mainImage: stock2,
        gallery: [stock3, stock4],
      },
      {
        id: 3,
        title: "Vehicle Management Dashboard",
        category: "ReactJS • Bootstrap • REST APIs",
        mainImage: stock3,
        gallery: [stock4, stock5],
      },
      {
        id: 4,
        title: "Mobility Solutions Portal",
        category: "Node.js • Express • PostgreSQL",
        mainImage: stock4,
        gallery: [stock, stock1],
      },
      {
        id: 5,
        title: "UI/UX Portfolio Website",
        category: "HTML5 • CSS3 • Animations",
        mainImage: stock5,
        gallery: [stock2, stock3],
      },
      {
        id: 6,
        title: "Cloud Deployment Pipeline",
        category: "AWS • CI/CD • Scalable Architecture",
        mainImage: stock1,
        gallery: [stock4, stock5],
      },
    ];

    return (
      <section id="work" className="portfolio-mf sect-pt4 route">
        <div className="container">
          <div className="row">
            <div className="col-sm-12">
              <div className="title-box text-center">
                <h3 className="title-a gradient-text">Portfolio</h3>
                <p className="subtitle-a glow-text">
                  A showcase of my projects — blending clean UI, scalable
                  backends, and smooth user experiences.
                </p>
                <div className="line-mf"></div>
              </div>
            </div>
          </div>

          <div className="row">
            {projects.map((project) => (
              <div className="col-md-4" key={project.id}>
                <div className="work-box">
                  <a href={project.mainImage} data-lightbox={`gallery-${project.id}`}>
                    <div className="work-img">
                      <img
                        src={project.mainImage}
                        alt={project.title}
                        className="img-fluid"
                      />
                    </div>
                    <div className="work-content">
                      <div className="row">
                        <div className="col-sm-8">
                          <h2 className="w-title">{project.title}</h2>
                          <div className="w-more">
                            <span className="w-ctegory">{project.category}</span>
                          </div>
                        </div>
                        <div className="col-sm-4">
                          <div className="w-like">
                            <span className="ion-ios-plus-outline"></span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </a>

                  {/* Hidden gallery images */}
                  {project.gallery.map((img, idx) => (
                    <a
                      href={img}
                      data-lightbox={`gallery-${project.id}`}
                      style={{ display: "none" }}
                      key={idx}
                    >
                      {project.title} extra
                    </a>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    );
  }
}

export default Portfolio;
